structure.mermaidSource:
flowchart TD
  start["Início: Auditoria de Vírgula na Proposta de Reescrita"] --> proc_identificar_eixo["Passo 1: Mapear o Eixo Sintático Fundamental (Su-Ve-C)"]
  proc_identificar_eixo --> dec_virgula_solteira{"Passo 2: Há vírgula solteira separando Sujeito-Verbo ou Verbo-Complemento?"}
  dec_virgula_solteira -- "Sim" --> res_item_incorreto_eixo["Item INCORRETO (Proibição Canônica de Pontuação)"]
  dec_virgula_solteira -- "Não" --> dec_ha_intercalacao{"Passo 3: Há termos intercalados entre duas vírgulas?"}
  dec_ha_intercalacao -- "Sim" --> proc_supressao_mental["Passo 3A: Teste da Supressão Mental"]
  dec_ha_intercalacao -- "Não" --> proc_analisar_adjunto["Passo 4: Auditoria de Adjuntos Adverbiais Deslocados"]
  proc_supressao_mental --> dec_continuidade_suvec{"Passo 3B: A frase remanescente mantém a continuidade Su-Ve-C perfeita?"}
  dec_continuidade_suvec -- "Não" --> res_item_incorreto_intercalacao["Item INCORRETO (Intercalação Defeituosa)"]
  dec_continuidade_suvec -- "Sim" --> proc_analisar_adjunto
  proc_analisar_adjunto --> dec_extensao_adjunto{"Qual a extensão do termo adverbial deslocado?"}
  dec_extensao_adjunto -- "Curta extensão (1 a 2 palavras)" --> res_facultativa["Item CORRETO: Vírgula Facultativa"]
  dec_extensao_adjunto -- "Longa extensão (3+ palavras / Oração)" --> dec_presenca_virgula{"A vírgula foi devidamente empregada?"}
  dec_extensao_adjunto -- "Sem termo deslocado" --> res_ordem_direta["Item CORRETO: Ordem Direta Canônica"]
  dec_presenca_virgula -- "Sim" --> res_obrigatoria_correta["Item CORRETO: Vírgula Obrigatória Mantida"]
  dec_presenca_virgula -- "Não" --> res_obrigatoria_omissa["Item INCORRETO: Omissão de Vírgula Obrigatória"]
